package ai.jobachiever.resumes.studio.dto;

import com.fasterxml.jackson.annotation.JsonAlias;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.util.ArrayList;
import java.util.List;

/**
 * Individual rewritten sentence, bullet, or summary option generated by the AI Writing Assistant.
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public class SuggestionItemDto {

    private String id;

    @JsonProperty("original_text")
    @JsonAlias({"original_text", "originalText", "original"})
    private String originalText;

    @JsonProperty("suggested_text")
    @JsonAlias({"suggested_text", "suggestedText", "rewritten"})
    private String suggestedText;

    private String reason;

    private List<String> changes = new ArrayList<>();

    @JsonProperty("preserved_facts")
    @JsonAlias({"preserved_facts", "preservedFacts"})
    private List<String> preservedFacts = new ArrayList<>();

    @JsonProperty("unsupported_claims")
    @JsonAlias({"unsupported_claims", "unsupportedClaims"})
    private List<String> unsupportedClaims = new ArrayList<>();

    private List<String> warnings = new ArrayList<>();

    private String confidence = "HIGH";

    @JsonProperty("writing_mode")
    @JsonAlias({"writing_mode", "writingMode"})
    private String writingMode;

    public SuggestionItemDto() {
    }

    public SuggestionItemDto(String id, String originalText, String suggestedText, String reason,
                             List<String> changes, List<String> preservedFacts, List<String> unsupportedClaims,
                             List<String> warnings, String confidence, String writingMode) {
        this.id = id;
        this.originalText = originalText;
        this.suggestedText = suggestedText;
        this.reason = reason;
        this.changes = changes != null ? changes : new ArrayList<>();
        this.preservedFacts = preservedFacts != null ? preservedFacts : new ArrayList<>();
        this.unsupportedClaims = unsupportedClaims != null ? unsupportedClaims : new ArrayList<>();
        this.warnings = warnings != null ? warnings : new ArrayList<>();
        this.confidence = confidence != null ? confidence : "HIGH";
        this.writingMode = writingMode;
    }

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private String id;
        private String originalText;
        private String suggestedText;
        private String reason;
        private List<String> changes = new ArrayList<>();
        private List<String> preservedFacts = new ArrayList<>();
        private List<String> unsupportedClaims = new ArrayList<>();
        private List<String> warnings = new ArrayList<>();
        private String confidence = "HIGH";
        private String writingMode;

        public Builder id(String id) {
            this.id = id;
            return this;
        }

        public Builder originalText(String originalText) {
            this.originalText = originalText;
            return this;
        }

        public Builder suggestedText(String suggestedText) {
            this.suggestedText = suggestedText;
            return this;
        }

        public Builder reason(String reason) {
            this.reason = reason;
            return this;
        }

        public Builder changes(List<String> changes) {
            this.changes = changes;
            return this;
        }

        public Builder preservedFacts(List<String> preservedFacts) {
            this.preservedFacts = preservedFacts;
            return this;
        }

        public Builder unsupportedClaims(List<String> unsupportedClaims) {
            this.unsupportedClaims = unsupportedClaims;
            return this;
        }

        public Builder warnings(List<String> warnings) {
            this.warnings = warnings;
            return this;
        }

        public Builder confidence(String confidence) {
            this.confidence = confidence;
            return this;
        }

        public Builder writingMode(String writingMode) {
            this.writingMode = writingMode;
            return this;
        }

        public SuggestionItemDto build() {
            return new SuggestionItemDto(id, originalText, suggestedText, reason, changes,
                    preservedFacts, unsupportedClaims, warnings, confidence, writingMode);
        }
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getOriginalText() {
        return originalText;
    }

    public void setOriginalText(String originalText) {
        this.originalText = originalText;
    }

    public String getSuggestedText() {
        return suggestedText;
    }

    public void setSuggestedText(String suggestedText) {
        this.suggestedText = suggestedText;
    }

    public String getReason() {
        return reason;
    }

    public void setReason(String reason) {
        this.reason = reason;
    }

    public List<String> getChanges() {
        return changes;
    }

    public void setChanges(List<String> changes) {
        this.changes = changes;
    }

    public List<String> getPreservedFacts() {
        return preservedFacts;
    }

    public void setPreservedFacts(List<String> preservedFacts) {
        this.preservedFacts = preservedFacts;
    }

    public List<String> getUnsupportedClaims() {
        return unsupportedClaims;
    }

    public void setUnsupportedClaims(List<String> unsupportedClaims) {
        this.unsupportedClaims = unsupportedClaims;
    }

    public List<String> getWarnings() {
        return warnings;
    }

    public void setWarnings(List<String> warnings) {
        this.warnings = warnings;
    }

    public String getConfidence() {
        return confidence;
    }

    public void setConfidence(String confidence) {
        this.confidence = confidence;
    }

    public String getWritingMode() {
        return writingMode;
    }

    public void setWritingMode(String writingMode) {
        this.writingMode = writingMode;
    }
}
